JS='''
(function(){
 const doc=document.documentElement;try{if(localStorage.getItem('aif-theme')==='dark')doc.classList.add('dark')}catch(e){}
 const theme=document.getElementById('themeToggle');if(theme){const refresh=()=>theme.textContent=doc.classList.contains('dark')?'☀ فاتح':'☾ داكن';refresh();theme.addEventListener('click',()=>{doc.classList.toggle('dark');try{localStorage.setItem('aif-theme',doc.classList.contains('dark')?'dark':'light')}catch(e){}refresh()})}
 const menu=document.getElementById('mobileMenu');if(menu)menu.addEventListener('click',()=>document.body.classList.toggle('menu-open'));
 document.querySelectorAll('.contents-links a').forEach(a=>a.addEventListener('click',()=>document.body.classList.remove('menu-open')));
 const cards=[...document.querySelectorAll('.study-card')],search=document.getElementById('searchInput'),counter=document.getElementById('searchCount');if(search){search.addEventListener('input',()=>{const q=search.value.trim().toLocaleLowerCase();let n=0;cards.forEach(c=>{let show=!q||c.textContent.toLocaleLowerCase().includes(q);c.classList.toggle('hidden-search',!show);if(show)n++});if(counter)counter.textContent=q?`نتائج البحث: ${n} قسم`:' ';})}
 const key='aif-progress-'+(document.body.dataset.volume||'home');let done=[];try{done=JSON.parse(localStorage.getItem(key)||'[]')}catch(e){}
 document.querySelectorAll('.complete-btn').forEach(b=>{const id=b.dataset.target;const redraw=()=>{let has=done.includes(id);b.classList.toggle('completed',has);b.textContent=has?'✓ تم إكمال هذا القسم':'○ علّم هذا القسم كمكتمل'};redraw();b.addEventListener('click',()=>{done=done.includes(id)?done.filter(x=>x!==id):[...done,id];try{localStorage.setItem(key,JSON.stringify(done))}catch(e){}redraw();updateProgress()})});
 function updateProgress(){const p=document.getElementById('studyDone');if(p)p.textContent=done.length+' / '+document.querySelectorAll('.complete-btn').length+' قسم مكتمل'}updateProgress();
 const bar=document.querySelector('.reading-progress');const onScroll=()=>{if(bar){let denom=document.documentElement.scrollHeight-innerHeight;bar.style.width=(denom>0?(scrollY/denom*100):0)+'%'}};window.addEventListener('scroll',onScroll,{passive:true});onScroll();
 if('IntersectionObserver' in window){const links=[...document.querySelectorAll('.contents-links a')];const obs=new IntersectionObserver(es=>{const vis=es.filter(e=>e.isIntersecting).sort((a,b)=>b.intersectionRatio-a.intersectionRatio)[0];if(vis){links.forEach(a=>a.classList.toggle('active',a.hash==='#'+vis.target.id))}},{rootMargin:'-90px 0px -60% 0px'});cards.forEach(c=>obs.observe(c))}
 const all=document.getElementById('toggleAnswers');if(all){let shown=false;all.addEventListener('click',()=>{shown=!shown;document.querySelectorAll('.answer-reveal').forEach(x=>x.open=shown);all.textContent=shown?'إخفاء مفتاح الإجابات':'عرض مفتاح الإجابات'})}
})();
'''
(ROOT/'assets'/'styles.css').write_text(CSS)
(ROOT/'assets'/'app.js').write_text(JS)
def shell(title, content, toc='', volume=None, description=''):
 sidebar=f'<div class="sidebar-label">المجلدات الخمسة</div>{NAV}<div class="sidebar-divider"></div>' + (f'<div class="sidebar-label">فهرس المجلد</div><div class="contents-links">{toc}</div>' if toc else '<div class="sidebar-label">AIF-C01 • 2026</div><p style="font-size:12px;color:var(--muted);padding:8px">المحتوى التعليمي مقتبس بنيويًا من الكتب الخمسة المُعدّة ضمن المشروع، مع الحفاظ على النصوص والرسومات الأصلية.</p>')
 return f'''<!DOCTYPE html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)} | AWS AI Practitioner Academy</title><meta name="description" content="{html.escape(description or title)}"><script src="https://cdn.tailwindcss.com"></script><link rel="stylesheet" href="assets/styles.css"></head><body data-volume="{volume or ''}"><div class="reading-progress"></div><header class="site-header"><button id="mobileMenu" class="nav-mobile" aria-label="فتح قائمة الفهرس">☰</button><a class="brand" href="index.html"><span class="brand-symbol">AI</span><span><span class="header-main">AWS AI Practitioner</span><small>Personal Academy • AIF-C01</small></span></a><span class="header-sub">مكتبة تعليمية عربية تفاعلية</span><div class="header-actions"><a class="top-pill" href="index.html">الرئيسية</a><button class="icon-btn" id="themeToggle" type="button">☾ داكن</button><button class="icon-btn" onclick="window.print()" type="button">⎙ طباعة</button></div></header><div class="page-layout"><aside class="sidebar">{sidebar}</aside><main class="main">{content}<footer class="footer">مرجع تعليمي مستقل • AWS Certified AI Practitioner (AIF-C01) • ليس منشورًا رسميًا من AWS</footer></main></div><script src="assets/app.js"></script></body></html>'''

def clean_source_section(sec):
 # Preserve structure/diagrams from source. Avoid embedded PDF print styles and font references.
 for item in sec.select('[style]'):
  st=item.get('style','')
  if item.name not in ('svg','g','path','rect','text','line','polyline','polygon','circle','ellipse'):
   if any(x in st for x in ('font:', 'font-size:', 'text-align:', 'background:', 'padding:', 'margin:', 'border:', 'direction:')):
    del item['style']
 # not modifying user authored content
 return sec

for idx,(src,ar,en,pct,name,num) in enumerate(SOURCES):
 soup=BeautifulSoup(Path(src).read_text(encoding='utf-8'),'html.parser')
 # Restore standalone question/answer blocks: the publishing sources place them as
 # siblings after their section headings, not nested within <section>.
 last_section=None
 for child in list(soup.body.children):
  if getattr(child,'name',None)=='section':last_section=child
  elif getattr(child,'name',None)=='div' and ('q' in child.get('class',[]) or 'question' in child.get('class',[]) or 'answer' in child.get('class',[])) and last_section is not None:
   last_section.append(child.extract())
 sections=soup.select('body > section')
 assembled=[]; toc=[]; seen=set(); answers=False
 for i,sec in enumerate(sections):
  if 'cover' in sec.get('class',[]):continue
  sec=clean_source_section(sec)
  head=sec.find(['h1','h2','h3'])
  label=head.get_text(' ',strip=True) if head else 'القسم '+str(i)
  ident=sec.get('id') or f'chapter-{num}-{i}'
  if ident in seen:ident=f'{ident}-{i}'
  sec['id']=ident;seen.add(ident)
  clazz=sec.get('class',[])
  sec['class']=['study-card']+[cl for cl in clazz if cl not in ('cover','toc','titlepage')]
  if 'answers' in clazz or ('book-divider' in clazz and ('الإجابات' in label or 'إجابات' in label)):
   answers=True
   # Wrap answers in collapsible details; ensure no leakage of answer when closed
   details=soup.new_tag('details',attrs={'class':'answer-reveal'})
   summary=soup.new_tag('summary'); summary.string='اضغط لإظهار شروح الإجابات — لا تفتح قبل حل الأسئلة'
   details.append(summary)
   inner=soup.new_tag('div')
   for child in list(sec.contents):inner.append(child.extract())
   details.append(inner)
   sec.append(details)
  # nested section ToC: some titles are very long; avoid overlong display
  short=label if len(label)<=65 else label[:62]+'…'
  toctype='nested' if 'objective' in clazz else ''
  if 'booksection' in clazz and label.startswith('TASK STATEMENT'):
   toctype=''
  toc.append(f'<a class="{toctype}" href="#{ident}" title="{html.escape(label,quote=True)}">{html.escape(short)}</a>')
  if ('lesson' in clazz or 'objective' in clazz or ('booksection' in clazz and label.startswith('TASK STATEMENT'))):
   ctl=soup.new_tag('div',attrs={'class':'chapter-actions'});btn=soup.new_tag('button',attrs={'class':'complete-btn','data-target':ident,'type':'button'});btn.string='○ علّم هذا القسم كمكتمل';ctl.append(btn);sec.append(ctl)
  assembled.append(str(sec))
 hero=f'''<div class="study-hero"><div class="eyebrow">AWS CERTIFIED AI PRACTITIONER — AIF-C01 / DOMAIN {num}</div><h1>{html.escape(ar)}</h1><div class="hero-en">{html.escape(en)}</div><div class="hero-tags"><span>المجلد {int(num)}</span><span>وزن الامتحان {pct}</span><span>شرح عربي + English Terms</span><span>أسئلة وتطبيقات</span></div></div>'''
